INSERT INTO "block_venue" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","name","address","description","note","time","is_free","location","opening_hours","google_maps_url","website","phone","best_of_award","grapevine_url","image") VALUES('22d1eb6clq','6fdtwwf6h9','content','section','r6l3y3jdhl','venues',1,'Röntgen','Hverfisgata 12','This is where the party kicks in. Late-night dancing, good drinks, reliably cool DJ lineup. The energy builds as the night goes on.','The disco ball doesn''t spin itself. And if you cut your fingers, they''ve got band-aids at the bar.','11:30 PM',0,'{"latitude":64.1471,"longitude":-21.933}','Mo 18-00; Tu-We 16-01; Th 14-01; Fr-Sa 14-03; Su 18-00','https://www.google.com/maps/search/Röntgen+bar+Hverfisgata+Reykjavik','rontgenbar.is','691 9662','Best Goddamn Bar 2026 — Reykjavík Grapevine','https://grapevine.is/best-of-reykjavik/2026/02/24/best-of-reykjavik-2026-best-goddamn-bar/',NULL);
INSERT INTO "block_venue" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","name","address","description","note","time","is_free","location","opening_hours","google_maps_url","website","phone","best_of_award","grapevine_url","image") VALUES('h3lgaen4rv','6fdtwwf6h9','content','section','r6l3y3jdhl','venues',1,'Kaffibarinn','Bergstaðastræti 1','Gritty, loud, packed, and an absolute Reykjavík institution. This is where nights end or spiral. No judgment. Just vibes.',NULL,'Bonus — Sometime in the AM',0,'{"latitude":64.1458,"longitude":-21.9349}',NULL,'https://www.google.com/maps/search/Kaffibarinn+Reykjavik',NULL,NULL,NULL,NULL,NULL);
INSERT INTO "block_venue" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","name","address","description","note","time","is_free","location","opening_hours","google_maps_url","website","phone","best_of_award","grapevine_url","image") VALUES('oxa3s8sjdo','nw9rviesmj','content','section','jgxxkfja6q','venues',1,'Matkráin','Hvergardi','Cozy, modern restaurant. Seasonal Icelandic ingredients, creative dishes that feel elevated without being stiff. Worth planning around.','Just 40 minutes from Reykjavík.',NULL,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "block_venue" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","name","address","description","note","time","is_free","location","opening_hours","google_maps_url","website","phone","best_of_award","grapevine_url","image") VALUES('o2mswg3hdo','nw9rviesmj','content','section','jgxxkfja6q','venues',1,'GK Bakarí','Selfoss','A proper Icelandic bakery. Flaky pastries, cinnamon rolls, and traditional cakes. Great for breakfast on the road.',NULL,NULL,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "block_venue" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","name","address","description","note","time","is_free","location","opening_hours","google_maps_url","website","phone","best_of_award","grapevine_url","image") VALUES('rokxit4yp6','nw9rviesmj','content','section','jgxxkfja6q','venues',1,'Friðheimar','Reykholt, just off the Golden Circle route','Dining inside a working tomato greenhouse. Unlimited tomato soup and freshly baked bread. Don''t skip the burrata or tomato beer. A must-stop.',NULL,NULL,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
