INSERT INTO "block_venue" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","name","address","description","note","time","is_free","location","opening_hours","google_maps_url","website","phone","best_of_award","grapevine_url","image") VALUES('6xzuaggitr','nw9rviesmj','content','section','jgxxkfja6q','venues',1,'Laugarás Lagoon + Ylja Restaurant','Laugarás (between Selfoss and Geysir)','New geothermal lagoon with a proper restaurant attached. Chef Gísli Matt (formerly Dill) runs the kitchen. Worth building your day around.',NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "block_venue" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","name","address","description","note","time","is_free","location","opening_hours","google_maps_url","website","phone","best_of_award","grapevine_url","image") VALUES('g77t1n6dtn','nw9rviesmj','content','section','jgxxkfja6q','venues',1,'Pylsuvagninn','Selfoss town center','Classic Icelandic hot dog stand. Order it með öllu (with everything). Quick, cheap, and very Icelandic.',NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "block_venue" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","name","address","description","note","time","is_free","location","opening_hours","google_maps_url","website","phone","best_of_award","grapevine_url","image") VALUES('z001l3hyu3','nw9rviesmj','content','section','jgxxkfja6q','venues',1,'Rauða Húsið','Eyrarbakki (coastal detour from Selfoss)','Historic red house in a fishing village. Known for the lobster soup — it’s earned the reputation. Good for a longer stop.',NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "block_venue" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","name","address","description","note","time","is_free","location","opening_hours","google_maps_url","website","phone","best_of_award","grapevine_url","image") VALUES('2uv02q57eb','nw9rviesmj','content','section','jgxxkfja6q','venues',1,'Flúðasveppir','Flúðir','Local mushroom farm serving lunch. Rich mushroom soup, hearty dishes. Low-key and local.',NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "block_venue" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","name","address","description","note","time","is_free","location","opening_hours","google_maps_url","website","phone","best_of_award","grapevine_url","image") VALUES('524oq3drkj','nw9rviesmj','content','section','jgxxkfja6q','venues',1,'Tommi''s Burger Joint','Selfoss','Old-school, no-nonsense burgers. Simple, affordable, consistently good. Classic cheeseburger with fries and a milkshake.',NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "block_venue" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","name","address","description","note","time","is_free","location","opening_hours","google_maps_url","website","phone","best_of_award","grapevine_url","image") VALUES('v1','7guc0nxad6','content','section','s1','venues',1,'Sandholt Bakery','Laugavegur 36','Kids eat free here — that alone earns it a spot. But it’s also just a lovely bakery. Sourdough, flaky pastries, and a cozy sit-in area. Grab a cinnamon roll for the toddler and a proper coffee for yourself. Mornings are calm before 9AM; after that it gets busy.','Kids eat free. Highchairs available.',NULL,1,'{"latitude":64.145,"longitude":-21.926}','Mo-Su 07:30-18:00','https://www.google.com/maps/search/Sandholt+Laugavegur+36+Reykjavik',NULL,NULL,'Best Bakery 2025 — Reykjavík Grapevine',NULL,NULL);
INSERT INTO "block_venue" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","name","address","description","note","time","is_free","location","opening_hours","google_maps_url","website","phone","best_of_award","grapevine_url","image") VALUES('v2','7guc0nxad6','content','section','s1','venues',1,'Laundromat Café','Austurstræti 9','The secret weapon: a basement play area filled with toys, books, and pillows. Drop the kids down there and enjoy your brunch in relative peace. Weekend brunch has pancakes, eggs, bacon, and fruit smoothies. Board games for the older ones.','Basement play area. Weekend brunch Sat-Sun 09:00-15:00.',NULL,1,'{"latitude":64.1474,"longitude":-21.9387}','Mo-Su 08:00-23:00','https://www.google.com/maps/search/Laundromat+Café+Austurstræti+Reykjavik',NULL,NULL,NULL,NULL,NULL);
INSERT INTO "block_venue" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","name","address","description","note","time","is_free","location","opening_hours","google_maps_url","website","phone","best_of_award","grapevine_url","image") VALUES('v3','7guc0nxad6','content','section','s1','venues',1,'Brauð & Co','Frakkastígur 16','Opens at 6:30AM for the early risers (or the parents who had no choice). Cinnamon buns the size of your toddler’s head. Pretzel croissants that keep little hands busy. Quick in-and-out — perfect for grabbing pastries before a walk around the pond.','Takeaway-friendly. No real seating for lingering with kids.',NULL,0,'{"latitude":64.144,"longitude":-21.9261}',NULL,'https://www.google.com/maps/search/Brau%C3%B0+Co+Frakkast%C3%ADgur+Reykjavik',NULL,NULL,NULL,NULL,NULL);
INSERT INTO "block_venue" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","name","address","description","note","time","is_free","location","opening_hours","google_maps_url","website","phone","best_of_award","grapevine_url","image") VALUES('v4','7guc0nxad6','content','section','s2','venues',1,'Le Kock','Tryggvagata 14','Sister restaurant to DEIG, and one of the most naturally family-friendly spots downtown. Legendary burgers in DEIG-made potato brioche buns. The space is relaxed, the staff are patient, and the food is genuinely good.','Highchairs available. Spacious enough for prams.',NULL,0,'{"latitude":64.1501,"longitude":-21.9434}','Mo-Su 11:30-22:00','https://www.google.com/maps/search/Le+Kock+Tryggvagata+Reykjavik','lekock.is',NULL,NULL,NULL,'td5cucw0c5');
INSERT INTO "block_venue" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","name","address","description","note","time","is_free","location","opening_hours","google_maps_url","website","phone","best_of_award","grapevine_url","image") VALUES('v5','7guc0nxad6','content','section','s2','venues',1,'Kaffi Lækur','Laugarnesvegur 75','A neighbourhood gem popular with new parents. Dedicated kids’ corner with toys and books. Sourdough flatbakes are hearty and delicious. Slightly off the tourist path.','Kids’ corner with toys and books.',NULL,0,'{"latitude":64.1422,"longitude":-21.9058}',NULL,'https://www.google.com/maps/search/Kaffi+L%C3%A6kur+Laugarnesvegur+Reykjavik',NULL,NULL,NULL,NULL,NULL);
INSERT INTO "block_venue" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","name","address","description","note","time","is_free","location","opening_hours","google_maps_url","website","phone","best_of_award","grapevine_url","image") VALUES('v6','7guc0nxad6','content','section','s2','venues',1,'Chickpea','Hallveigastígur 1','Family-run vegetarian spot with the best falafel in town. Generous portions, freshly made, warm and unhurried vibe. Great for kids who like wraps and hummus.','Vegetarian/vegan. Casual and quick.',NULL,0,'{"latitude":64.1457,"longitude":-21.9341}','Mo-Su 10:00-20:00','https://www.google.com/maps/search/Chickpea+Reykjavik','chickpea.is',NULL,NULL,NULL,'e59v159sv3');
INSERT INTO "block_venue" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","name","address","description","note","time","is_free","location","opening_hours","google_maps_url","website","phone","best_of_award","grapevine_url","image") VALUES('v7','7guc0nxad6','content','section','s2','venues',1,'La Poblana','Laugavegur 12, 2nd floor','Authentic Mexican food on the second floor of Laugavegur 12. Family-run, using recipes from Puebla. Way more than just tacos — enchiladas in salsa verde, quesadillas, burritos, and plenty of other dishes. Everything is customisable and most items work great as kid food: small portions, handheld, easy to share. Vegetarian and gluten-free options if your little one has restrictions. Warm, unhurried vibe.','Family-run. Full Mexican menu beyond tacos. Vegetarian, vegan and gluten-free options.',NULL,0,'{"latitude":64.1468,"longitude":-21.9308}','Su-Th 12:00-21:00; Fr-Sa 12:00-21:00','https://www.google.com/maps/search/La+Poblana+Laugavegur+Reykjavik','lapoblana.is','760 7221',NULL,NULL,'nkpti6fxvu');
INSERT INTO "block_venue" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","name","address","description","note","time","is_free","location","opening_hours","google_maps_url","website","phone","best_of_award","grapevine_url","image") VALUES('v8','7guc0nxad6','content','section','s2','venues',1,'Plantan Bistro (Norræna húsið)','Sturlugata 5','Plant-based bistro inside the Nordic House — an Alvar Aalto-designed cultural gem. Come for lunch, stay for the library. The kids’ section has children’s literature in Nordic languages, a play area, and storytelling hours in winter. Free library card. Perfect rainy-day combo: eat, read, explore.','Nordic House library with dedicated kids’ section, play area, and storytelling hours. Open Tue–Sun.',NULL,0,'{"latitude":64.142,"longitude":-21.9508}','Mo-Su 11:00-17:00','https://www.google.com/maps/search/Plantan+Bistro+Norraena+husid+Reykjavik','plantankaffihus.is','551 7030',NULL,NULL,NULL);
INSERT INTO "block_venue" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","name","address","description","note","time","is_free","location","opening_hours","google_maps_url","website","phone","best_of_award","grapevine_url","image") VALUES('v9','7guc0nxad6','content','section','s3','venues',1,'Búllan','Geirsgata 1','Multiple locations around town, but the Geirsgata spot by the old harbour is the one most visitors will hit first. No-frills burgers, zero pretension, walls covered in kids’ drawings — your kids can add to the collection. The Höfði branch (Bolholt 6) is perfect if you’re on your way out of town.','Multiple locations. Geirsgata for downtown, Höfði (Bolholt 6) on the way out of town.',NULL,0,'{"latitude":64.1512,"longitude":-21.9443}',NULL,'https://www.google.com/maps/search/B%C3%BAllan+Geirsgata+Reykjavik',NULL,NULL,NULL,NULL,'t6gzo781k7');
INSERT INTO "block_venue" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","name","address","description","note","time","is_free","location","opening_hours","google_maps_url","website","phone","best_of_award","grapevine_url","image") VALUES('v10','7guc0nxad6','content','section','s3','venues',1,'Jómfrúin','Lækjargata 4','Classic Danish smørrebrød — open-faced sandwiches perfect for kids who like to pick and choose toppings. Best service in town means they’ll be patient with your order taking twice as long.','Best service in town. Patient with families.',NULL,0,'{"latitude":64.1468,"longitude":-21.9374}','Mo-Su 11:30-22:00','https://www.google.com/maps/search/J%C3%B3mfr%C3%BAin+L%C3%A6kjargata+Reykjavik',NULL,'551 0100',NULL,NULL,'qzs1eqbdl3');
INSERT INTO "block_venue" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","name","address","description","note","time","is_free","location","opening_hours","google_maps_url","website","phone","best_of_award","grapevine_url","image") VALUES('v11','7guc0nxad6','content','section','s3','venues',1,'2guys','Laugavegur 105 (Hlemmur)','Award-winning burgers at Hlemmur — voted Best Burger in Reykjavík four years running. They have a proper kids’ menu: Klemma burger, fries and juice for 1,500 ISK. The vibe is relaxed enough that nobody bats an eye at a messy eater. Great veggie options too.','Kids’ menu available (1,500 ISK). Best Burger 2023–2026.',NULL,0,'{"latitude":64.1428,"longitude":-21.9148}','Mo-Su 11:30-21:00','https://www.google.com/maps/search/2guys+Laugavegur+105+Reykjavik','2guys.is','790 2323',NULL,NULL,NULL);
INSERT INTO "block_venue" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","name","address","description","note","time","is_free","location","opening_hours","google_maps_url","website","phone","best_of_award","grapevine_url","image") VALUES('v12','7guc0nxad6','content','section','s3','venues',1,'Just Wing’in It','Snorrabraut 56','Over 30 wing flavours plus chicken tenders for the less adventurous. The real draw for kids: corn hole tossing and shuffleboard to keep them busy while you eat. Casual, loud, zero judgement — basically designed for families even if they didn’t mean to be.','Games for kids (corn hole, shuffleboard). Takeaway available.',NULL,0,'{"latitude":64.143,"longitude":-21.915}','Mo-Su 11:30-21:00','https://www.google.com/maps/search/Just+Wingin+It+Snorrabraut+Reykjavik','justwinginit.is','661 2878',NULL,NULL,NULL);
INSERT INTO "block_venue" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","name","address","description","note","time","is_free","location","opening_hours","google_maps_url","website","phone","best_of_award","grapevine_url","image") VALUES('v13','7guc0nxad6','content','section','s4','venues',1,'DEIG Workshop','Tryggvagata 14','Doughnuts and bagels made fresh daily. The doughnuts are the obvious kid-magnet, but don’t sleep on the bagels. Perfect post-playground bribe.','Right next to Le Kock — easy to combine visits.',NULL,0,'{"latitude":64.1501,"longitude":-21.9434}','Mo-Fr 07:00-17:00; Sa-Su 08:00-16:00','https://www.google.com/maps/search/DEIG+Workshop+Tryggvagata+Reykjavik',NULL,NULL,NULL,NULL,NULL);
INSERT INTO "block_venue" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","name","address","description","note","time","is_free","location","opening_hours","google_maps_url","website","phone","best_of_award","grapevine_url","image") VALUES('v14','7guc0nxad6','content','section','s4','venues',1,'Mokka Kaffi','Skólavörðustígur 3a','Open since 1958 and barely changed since — red carpet, leatherette booths, rotating art on the walls. The waffles with cream and jam are the reason you’re here. Kids love them, you’ll love the espresso (Mokka was the first café in Iceland to serve it). A Reykjavík institution.','Open since 1958. Famous waffles with cream and jam.',NULL,0,'{"latitude":64.1441,"longitude":-21.9278}','Mo-Su 09:00-18:00','https://www.google.com/maps/search/Mokka+Kaffi+Sk%C3%B3lav%C3%B6r%C3%B0ust%C3%ADgur+Reykjavik','mokka.is','552 1174',NULL,NULL,NULL);
INSERT INTO "block_venue" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","name","address","description","note","time","is_free","location","opening_hours","google_maps_url","website","phone","best_of_award","grapevine_url","image") VALUES('v15','7guc0nxad6','content','section','s4','venues',1,'Gaeta Gelato','Aðalstræti 6 (Ingólfstorg)','Proper Italian gelato made fresh daily on Ingólfstorg. Pistachio, salted caramel, and seasonal flavours — plus cannoli and tiramisu if the kids want to branch out. The owners have nearly 25 years of experience as gelato makers. Open late, perfect for a post-dinner stroll.','Fresh gelato daily. Open until 23:00.',NULL,0,'{"latitude":64.1477,"longitude":-21.9399}','Mo-Su 12:30-23:00','https://www.google.com/maps/search/Gaeta+Gelato+Ingolfstorg+Reykjavik','gelato.is',NULL,NULL,NULL,NULL);
